function setLight(value){lighting=value;const configs={day:{bg:'#e7ede3',sun:'#fff3dc',intensity:3.2,hemi:2.2,pos:[-6,10,8],exposure:1.12},sunset:{bg:'#decbb4',sun:'#ffb56c',intensity:3.0,hemi:1.35,pos:[-9,3.4,5],exposure:1.12},night:{bg:'#1a2e32',sun:'#b9cee3',intensity:.6,hemi:.55,pos:[5,8,-7],exposure:1.15}};const c=configs[value];scene.background.set(c.bg);scene.fog.color.set(c.bg);house.base.material.color.set(c.bg);sun.color.set(c.sun);sun.intensity=c.intensity;sun.position.set(...c.pos);hemi.intensity=c.hemi;renderer.toneMappingExposure=c.exposure;document.body.classList.toggle('night',value==='night');$$('[data-light]').forEach(b=>b.classList.toggle('active',b.dataset.light===value));updateLights();}
