const thumbCache=new Map();let thumbRenderer;
function thumbnail(type){if(thumbCache.has(type))return thumbCache.get(type);try{if(!thumbRenderer){thumbRenderer=new T.WebGLRenderer({antialias:true,alpha:false,preserveDrawingBuffer:true});thumbRenderer.setSize(240,170);thumbRenderer.setPixelRatio(1);thumbRenderer.toneMapping=T.ACESFilmicToneMapping;thumbRenderer.toneMappingExposure=1.25;}const ts=new T.Scene();ts.background=new T.Color('#edf1e9');ts.add(new T.HemisphereLight('#fff8e9','#b0b7a1',2.7));const light=new T.DirectionalLight('#fff5de',3);light.position.set(-3,5,4);ts.add(light);const o=item(type,0,0),m=furnitureModel(o);m.position.set(0,0,0);ts.add(m);const b=new T.Box3().setFromObject(m),center=b.getCenter(new T.Vector3()),sz=b.getSize(new T.Vector3()),len=Math.max(sz.x,sz.y,sz.z);const c=new T.PerspectiveCamera(37,240/170,.01,100);c.position.copy(center).add(new T.Vector3(1.5,1.25,1.8).multiplyScalar(len*.83));c.lookAt(center);thumbRenderer.render(ts,c);const uri=thumbRenderer.domElement.toDataURL();thumbCache.set(type,uri);disposeModel(m);return uri;}catch{return '';}}
function renderPresets(){$('#presetCards').innerHTML=PRESETS.map((p,i)=>`<button class="preset-card ${state.preset===p.id?'active':''}" data-preset="${p.id}"><img alt="" src="${thumbnail(['bed5','loft35','sofabed'][i])}"><span><b>${p.name}</b><small>${p.subtitle}</small></span></button>`).join('');$$('[data-preset]').forEach(b=>b.onclick=()=>applyPreset(b.dataset.preset));}
let category='All';const categories=['All',...new Set(CATALOG.map(o=>o.cat))];
