function addItem(type){if(state.items.length>=180){toast('This layout has reached the 180-item limit.');return;}checkpoint();let o=item(type,0,.5),placed=false;const candidates=[];for(let z=1.5;z>-2;z-=.25)for(let x=-1.8;x<2;x+=.25)candidates.push({x,z});for(const p of candidates){o.x=Math.round(p.x*10)/10;o.z=Math.round(p.z*10)/10;if(!itemWarnings(o,state.items).some(t=>!t.startsWith('Loft:'))){placed=true;break;}}if(!placed){o.x=3.25;o.z=.6;toast('Added beside the house. Drag it into position.');}else toast(`${definitions[type].name} added.`);state.items.push(o);state.preset='custom';state.name='My little house';selectedId=o.id;commit();}
function selected(){return state.items.find(o=>o.id===selectedId);}
function updateSelection(){const m=models.get(selectedId);selection.visible=!!m&&mode==='decorate';if(m){m.updateMatrixWorld(true);selection.box.setFromObject(m);selection.material.color.set(itemWarnings(selected(),state.items).some(t=>t.startsWith('Overlaps'))?'#d06c51':'#3f7c59');}$('#inspector').hidden=!m||mode!=='decorate';}
