function changeSelected(mutator){const o=selected();if(!o)return;checkpoint();mutator(o);state.preset='custom';commit();}
function renderInspector(){const o=selected(),panel=$('#inspector');panel.hidden=!o||mode!=='decorate';if(!o)return;const def=definitions[o.type],warnings=itemWarnings(o,state.items);panel.innerHTML=`<div class="inspector-head"><div><span class="eyebrow">SELECTED OBJECT</span><h3>${def.name}</h3></div><button id="closeInspector" class="icon-btn" aria-label="Deselect">${icon('close')}</button></div><div class="row"><label class="field-label">X · metres<input id="objectX" type="number" min="-6" max="6" step=".1" value="${o.x.toFixed(2)}"></label><label class="field-label">Z · metres<input id="objectZ" type="number" min="-6" max="6" step=".1" value="${o.z.toFixed(2)}"></label></div><div class="row"><label class="field-label">Width<input id="objectW" type="number" min=".1" max="4" step=".05" value="${o.w.toFixed(2)}"></label><label class="field-label">Depth<input id="objectD" type="number" min=".1" max="4" step=".05" value="${o.d.toFixed(2)}"></label><label class="field-label">Height<input id="objectH" type="number" min=".01" max="3" step=".05" value="${o.h.toFixed(2)}"></label></div><label class="field-label">Rotation · degrees<input id="objectRotation" type="number" step="15" value="${Math.round(o.rot*180/Math.PI)}"></label><div class="swatches">${['#d9d7c8','#c6ac83','#a7b7a0','#425956','#343b3b','#d7a681','#eeeeea'].map(c=>`<button class="${o.color===c?'active':''}" style="background:${c}" data-color="${c}" title="Colour ${c}" aria-label="Colour ${c}"></button>`).join('')}<input id="customColor" type="color" value="${o.color}" aria-label="Custom colour" style="width:27px;height:27px;border:0;padding:0"></div>${def.kind==='sofabed'?`<button id="sofaToggle" class="btn wide secondary">${o.open?'Fold into sofa':'Unfold into bed'}</button>`:''}<div class="button-row"><button id="rotateObject" class="btn secondary" title="Rotate 90 degrees">${icon('rotate')}90°</button><button id="duplicateObject" class="icon-btn" title="Duplicate" aria-label="Duplicate">${icon('copy')}</button><button id="deleteObject" class="icon-btn danger" title="Delete" aria-label="Delete">${icon('trash')}</button></div>${warnings.length?warnings.map(t=>`<p class="warning">${t}</p>`).join(''):'<p class="good">✓ No object or wall overlap detected.</p>'}<p>Dimensions include the model frame. Resize to match your actual furniture. Arrow keys nudge by ${snap?'10':'2'} cm.</p>`;
 $('#closeInspector').onclick=()=>select(null);for(const [id,k,min,max] of [['objectX','x',-6,6],['objectZ','z',-6,6],['objectW','w',.1,4],['objectD','d',.1,4],['objectH','h',.01,3]])$('#'+id).onchange=e=>{const v=Number(e.target.value);if(!Number.isFinite(v)||v<min||v>max){toast(`Use a value from ${min} to ${max}.`);renderInspector();return;}changeSelected(o=>o[k]=v);};$('#objectRotation').onchange=e=>{const v=Number(e.target.value);if(Number.isFinite(v))changeSelected(o=>o.rot=((v%360)+360)%360*Math.PI/180);};$$('[data-color]').forEach(b=>b.onclick=()=>changeSelected(o=>o.color=b.dataset.color));$('#customColor').onchange=e=>changeSelected(o=>o.color=e.target.value);$('#rotateObject').onclick=()=>rotateItem();$('#duplicateObject').onclick=duplicateItem;$('#deleteObject').onclick=deleteItem;if($('#sofaToggle'))$('#sofaToggle').onclick=()=>changeSelected(o=>o.open=!o.open);
}
function rotateItem(){changeSelected(o=>o.rot=(o.rot+Math.PI/2)%(Math.PI*2));}
function duplicateItem(){if(!selected()||state.items.length>=180)return;checkpoint();const o={...selected(),id:uid(),x:Math.min(6,selected().x+.35),z:Math.min(6,selected().z+.35)};state.items.push(o);selectedId=o.id;commit();toast('Duplicated. Move the new item into place.');}
function deleteItem(){if(!selectedId)return;checkpoint();state.items=state.items.filter(o=>o.id!==selectedId);selectedId=null;commit();toast('Object removed. Undo is available.');}

const raycaster=new T.Raycaster(),mouse=new T.Vector2(),floorPlane=new T.Plane(new T.Vector3(0,1,0),-FLOOR),groundPoint=new T.Vector3();
function ray(e){const r=renderer.domElement.getBoundingClientRect();mouse.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);raycaster.setFromCamera(mouse,camera);}
function pointAt(e){ray(e);return raycaster.ray.intersectPlane(floorPlane,groundPoint)?.clone();}
function pick(e){ray(e);const hits=raycaster.intersectObjects([...models.values()],true);for(const h of hits){let o=h.object;while(o&&!o.userData.itemId)o=o.parent;if(o)return o.userData.itemId;}return null;}
renderer.domElement.addEventListener('pointerdown',e=>{if(e.button!==0)return;lastPointer={x:e.clientX,y:e.clientY,id:e.pointerId};if(mode==='decorate'&&!measureMode){const id=pick(e);if(id){select(id);const p=pointAt(e),o=selected();if(p){drag={id,dx:o.x-p.x,dz:o.z-p.z,started:false};controls.enabled=false;renderer.domElement.setPointerCapture(e.pointerId);}return;}}},true);
renderer.domElement.addEventListener('pointermove',e=>{if(!drag||!lastPointer)return;if(Math.hypot(e.clientX-lastPointer.x,e.clientY-lastPointer.y)<4&&!drag.started)return;if(!drag.started){checkpoint();drag.started=true;stopWalking(false);}const p=pointAt(e),o=selected();if(!p||!o)return;const step=snap?.1:.01;o.x=Math.max(-6,Math.min(6,Math.round((p.x+drag.dx)/step)*step));o.z=Math.max(-6,Math.min(6,Math.round((p.z+drag.dz)/step)*step));const m=models.get(o.id);m.position.set(o.x,surfaceHeight(o.x,o.z)+.015,o.z);updateSelection();});
renderer.domElement.addEventListener('pointerup',e=>{if(e.button!==0)return;const moved=lastPointer&&Math.hypot(e.clientX-lastPointer.x,e.clientY-lastPointer.y)>5;if(drag){if(drag.started){state.preset='custom';commit(false);}drag=null;controls.enabled=true;lastPointer=null;return;}if(!moved&&lastPointer){const p=pointAt(e);if(measureMode&&p)addMeasurement(p);else if(mode==='simulate'&&p)walkToPoint({x:p.x,z:p.z});else if(mode==='decorate')select(pick(e));}lastPointer=null;});
renderer.domElement.addEventListener('pointercancel',()=>{if(drag?.started)commit(false);drag=null;controls.enabled=true;lastPointer=null;});
window.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||document.querySelector('dialog[open]'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redo();return;}if(e.key==='Escape'){select(null);if(document.body.classList.contains('presentation'))present(false);if(measureMode)toggleMeasure();return;}if(mode!=='decorate'||!selected())return;if(e.key.toLowerCase()==='r')rotateItem();if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteItem();}if(e.key.startsWith('Arrow')){e.preventDefault();const step=snap?.1:.02;changeSelected(o=>{if(e.key==='ArrowLeft')o.x=Math.max(-6,o.x-step);if(e.key==='ArrowRight')o.x=Math.min(6,o.x+step);if(e.key==='ArrowUp')o.z=Math.max(-6,o.z-step);if(e.key==='ArrowDown')o.z=Math.min(6,o.z+step);});}});

function emptyGroup(g){while(g.children.length){const c=g.children[0];g.remove(c);if(c.userData.disposable){c.geometry?.dispose();c.material?.map?.dispose();c.material?.dispose();}}}
function line(group,points,color='#58845e',dashed=false){const geometry=new T.BufferGeometry().setFromPoints(points.map(p=>new T.Vector3(...p)));const material=dashed?new T.LineDashedMaterial({color,dashSize:.10,gapSize:.07,depthTest:false}):new T.LineBasicMaterial({color,depthTest:false});const m=new T.Line(geometry,material);m.userData.disposable=true;m.renderOrder=10;if(dashed)m.computeLineDistances();group.add(m);return m;}
function label(group,text,x,y,z,scale=1){const c=document.createElement('canvas');c.width=512;c.height=128;const ctx=c.getContext('2d');ctx.fillStyle='#f9fcf5';ctx.beginPath();ctx.roundRect(3,5,506,116,22);ctx.fill();ctx.fillStyle='#294b3d';ctx.font='500 49px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text,256,65);const tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;const m=new T.Sprite(new T.SpriteMaterial({map:tex,depthTest:false,transparent:true}));m.position.set(x,y,z);m.scale.set(1.2*scale,.30*scale,1);m.renderOrder=20;m.userData.disposable=true;group.add(m);return m;}
function dimension(a,b,text){line(dimensionGroup,[a,b]);for(const p of [a,b])line(dimensionGroup,[[p[0]-.06,p[1],p[2]-.06],[p[0]+.06,p[1],p[2]+.06]]);label(dimensionGroup,text,(a[0]+b[0])/2,.5,(a[2]+b[2])/2,.85);}
function updateDimensions(){emptyGroup(dimensionGroup);emptyGroup(clearanceGroup);const s=state.structure,b=s.bounds,q=s.bathroom;
 dimension([b.left,.43,b.front+.88],[b.right,.43,b.front+.88],`${(b.right-b.left).toFixed(2)} m`);
 dimension([b.right+.70,.43,b.back],[b.right+.70,.43,b.front],`${(b.front-b.back).toFixed(2)} m`);
 dimension([q.x-q.w/2-.36,.43,q.z-q.d/2],[q.x-q.w/2-.36,.43,q.z+q.d/2],`${q.d.toFixed(2)} m`);
 dimension([q.x-q.w/2,.43,q.z+q.d/2+.28],[q.x+q.w/2,.43,q.z+q.d/2+.28],`${q.w.toFixed(2)} m`);
 dimension([b.left,.43,b.back-s.balcony.depth-.35],[b.right,.43,b.back-s.balcony.depth-.35],`${(b.right-b.left).toFixed(2)} m balcony`);
 for(const o of s.openings.filter(o=>o.kind==='door')){const w=wallSpec(s,o.side),x=w.axis==='x'?o.at:w.fixed,z=w.axis==='x'?w.fixed:o.at,ww=w.axis==='x'?o.w:.58,dd=w.axis==='x'?.58:o.w;line(clearanceGroup,[[x-ww/2,FLOOR+.019,z-dd/2],[x+ww/2,FLOOR+.019,z-dd/2],[x+ww/2,FLOOR+.019,z+dd/2],[x-ww/2,FLOOR+.019,z+dd/2],[x-ww/2,FLOOR+.019,z-dd/2]],'#bb9561',true);}
}
let measurePoints=[];function toggleMeasure(){measureMode=!measureMode;$('#measureBtn').classList.toggle('active',measureMode);$('#measureReadout').hidden=!measureMode;measurePoints=[];emptyGroup(measureGroup);$('#measureReadout').textContent='Click two points on the floor.';renderer.domElement.style.cursor=measureMode?'crosshair':'';}
function addMeasurement(p){if(measurePoints.length===2){measurePoints=[];emptyGroup(measureGroup);}p.y=FLOOR+.035;measurePoints.push(p);const dot=new T.Mesh(new T.SphereGeometry(.035,12,8),new T.MeshBasicMaterial({color:'#285747',depthTest:false}));dot.position.copy(p);dot.userData.disposable=true;measureGroup.add(dot);if(measurePoints.length===2){const [a,b]=measurePoints,distance=a.distanceTo(b);line(measureGroup,[a.toArray(),b.toArray()],'#285747');label(measureGroup,distance.toFixed(2)+' m',(a.x+b.x)/2,.52,(a.z+b.z)/2);$('#measureReadout').textContent=`${distance.toFixed(2)} m floor distance · click to start again`;}}
updateDimensions();

function setPersonStatus(text,detail){$('#personStatus').textContent=text;$('#personDetail').textContent=detail||'Click the floor to walk somewhere.';}
function stopWalking(show=true){const old=walking.action;if(old?.item&&walking.phase!=='walking'&&walking.phase!=='idle')blocky.root.position.set(old.x,surfaceHeight(old.x,old.z)+.015,old.z);walking={path:[],index:0,action:null,phase:'idle',elapsed:0,transition:null,routine:false,routineIndex:0,wait:0};emptyGroup(routeGroup);blocky.reset();const p=personPos();blocky.root.position.y=surfaceHeight(p.x,p.z)+.015;if(show){ensurePersonFree();setPersonStatus('Ready to explore');}else if(mode==='simulate'){ensurePersonFree();setPersonStatus('Ready to explore');}}
function resetPerson(){stopWalking(false);blocky.root.position.set(0,FLOOR+.015,1.3);blocky.root.rotation.y=0;ensurePersonFree();setPersonStatus('Ready to explore');}
function ensurePersonFree(){const p=personPos(),obs=navObstacles(state.items,personHeight),r=personRadius(personHeight);if(!pointBlocked(p.x,p.z,obs,r))return;const candidates=[{x:0,z:1.3},{x:0,z:2},{x:0,z:3.5}];for(let z=-2;z<2;z+=.2)for(let x=-2;x<2;x+=.2)candidates.push({x,z});const q=candidates.find(q=>!pointBlocked(q.x,q.z,obs,r));if(q){blocky.root.position.set(q.x,surfaceHeight(q.x,q.z)+.015,q.z);}}
function drawRoute(path){emptyGroup(routeGroup);routeGroup.visible=$('#pathToggle').checked;if(!path?.length)return;line(routeGroup,path.map(p=>[p.x,surfaceHeight(p.x,p.z)+.035,p.z]),'#397b5e',true);const p=path[path.length-1];const ring=new T.Mesh(new T.RingGeometry(.12,.16,32),new T.MeshBasicMaterial({color:'#4d8d68',side:T.DoubleSide,depthTest:false}));ring.rotation.x=-Math.PI/2;ring.position.set(p.x,surfaceHeight(p.x,p.z)+.04,p.z);ring.userData.disposable=true;routeGroup.add(ring);}
function startPath(path,action=null,keepRoutine=false){const routine=walking.routine,routineIndex=walking.routineIndex;blocky.reset();walking={path,index:0,action,phase:'walking',elapsed:0,transition:null,routine:keepRoutine&&routine,routineIndex,wait:0};drawRoute(path);setPersonStatus('Walking…',action?.label||'Finding a little breathing room.');}
function walkToPoint(point){stopWalking(false);ensurePersonFree();const path=findPath(personPos(),point,state.items,personHeight);if(!path){toast('No walkable route there. Try a clear floor area or move the blocking furniture.');setPersonStatus('That spot is blocked','Try another spot, or make more room.');return;}startPath(path);}
function action(name,keepRoutine=false){
 if(name==='tour'){stopWalking(false);walking.routine=true;walking.routineIndex=0;action('desk',true);return;}
 if(!keepRoutine)stopWalking(false);else{blocky.reset();ensurePersonFree();}
 if(name==='bed'){const sofa=state.items.find(o=>definitions[o.type].kind==='sofabed');if(sofa&&!sofa.open&&!state.items.some(o=>['bed','loft'].includes(definitions[o.type].kind))){checkpoint();sofa.open=true;rebuild();save();updateHistory();}}
 const options=destination(name,state.items);if(!options.length){toast(`Add ${name==='bed'?'a bed':'a desk'} first.`);setPersonStatus('Destination not available');walking.routine=false;return;}
 let chosen=null,path=null;for(const candidate of options){const p=findPath(personPos(),candidate,state.items,personHeight);if(p&&(!path||p.length<path.length)){chosen=candidate;path=p;}}
 if(!path){toast('Route blocked. Move furniture, resize it, or check the door clearances.');setPersonStatus('Cannot reach '+name,'The walking route is blocked.');walking.routine=false;return;}startPath(path,chosen,keepRoutine);
}
function arrive(){walking.phase='rest';walking.elapsed=0;walking.path=[];emptyGroup(routeGroup);const a=walking.action;if(!a){setPersonStatus('Arrived');return;}if(a.pose==='sleep'&&a.item){const o=state.items.find(i=>i.id===a.item.id);if(!o){stopWalking();return;}const kind=definitions[o.type].kind;const center=worldPoint(o,0,kind==='sofabed'?.65*o.d/definitions[o.type].d:0);const top=kind==='loft'?o.h*1.88/2.25:kind==='sofabed'?o.h*.45/.84:o.h*.55/definitions[o.type].h;walking.phase='settle';walking.transition={from:blocky.root.position.clone(),to:new T.Vector3(center.x,surfaceHeight(center.x,center.z)+top+.10,center.z),yaw:o.rot,pose:'sleep',loft:kind==='loft',duration:kind==='loft'?2.8:1.1};setPersonStatus(kind==='loft'?'Climbing up…':'Getting comfortable…','A simplified pose transition; not an ergonomic test.');}else if(a.pose==='sit'&&a.item){const o=a.item;walking.phase='settle';walking.transition={from:blocky.root.position.clone(),to:new T.Vector3(o.x,surfaceHeight(o.x,o.z)+.015,o.z),yaw:o.rot,pose:'sit',duration:.85};setPersonStatus('Taking a seat…');}else{setPersonStatus(a.label);walking.wait=0;}}
function updatePerson(dt,time){
 const g=blocky.root;g.scale.setScalar(personHeight/1.70);
 if(walking.phase==='walking'){
  let distance=dt*.92;while(distance>0&&walking.index<walking.path.length){const p=walking.path[walking.index],dx=p.x-g.position.x,dz=p.z-g.position.z,dist=Math.hypot(dx,dz);if(dist<.001){walking.index++;continue;}g.rotation.y=Math.atan2(dx,dz);const step=Math.min(distance,dist);g.position.x+=dx/dist*step;g.position.z+=dz/dist*step;distance-=step;if(step>=dist-.0001)walking.index++;}
  g.position.y=surfaceHeight(g.position.x,g.position.z)+.015;blocky.legs[0].rotation.x=Math.sin(time*9)*.32;blocky.legs[1].rotation.x=-Math.sin(time*9)*.32;blocky.arms[0].rotation.x=-Math.sin(time*9)*.31;blocky.arms[1].rotation.x=Math.sin(time*9)*.31;blocky.body.position.y=Math.abs(Math.sin(time*9))*.018;
  if(walking.index>=walking.path.length){blocky.reset();arrive();}
 }else if(walking.phase==='settle'){
  const tr=walking.transition;walking.elapsed+=dt;let t=Math.min(1,walking.elapsed/tr.duration),ease=t*t*(3-2*t);g.rotation.y=tr.yaw;g.position.lerpVectors(tr.from,tr.to,ease);if(tr.pose==='sleep'){const k=tr.loft?Math.max(0,(t-.65)/.35):ease;blocky.body.rotation.x=-Math.PI/2*k;blocky.body.position.z=.72*k;blocky.body.position.y=0;}else{blocky.body.position.y=-.32*ease;for(const l of blocky.legs)l.rotation.x=-Math.PI/2*ease;for(const a of blocky.arms)a.rotation.x=-.6*ease;}
  if(t===1){walking.phase='rest';walking.wait=0;setPersonStatus(tr.pose==='sleep'?'Resting on the bed':'Working at the desk',tr.pose==='sleep'?'Stop / stand up to get moving again.':'Taking a seat, six-block style.');}
 }else if(walking.phase==='rest'&&walking.routine){walking.wait+=dt;if(walking.wait>3){const routine=['desk','bathroom','balcony','bed','entrance'];walking.routineIndex=(walking.routineIndex+1)%routine.length;const prev=walking.action;if(prev){blocky.reset();g.position.set(prev.x,surfaceHeight(prev.x,prev.z)+.015,prev.z);}action(routine[walking.routineIndex],true);}}
 const x=g.position.x,z=g.position.z;const nearFront=Math.hypot(x,z-2.3)<1.2,nearBack=Math.hypot(x-1.65,z+2.3)<1.1,nearBath=Math.hypot(x+2.175,z-.05)<1.1;const factor=Math.min(1,dt*5);house.frontLeaf.position.x=T.MathUtils.lerp(house.frontLeaf.position.x,nearFront?.94:0,factor);house.rearPivot.rotation.y=T.MathUtils.lerp(house.rearPivot.rotation.y,nearBack?-1.4:0,factor);house.bathLeaf.position.x=T.MathUtils.lerp(house.bathLeaf.position.x,nearBath?.79:0,factor);
 if(follow&&mode==='simulate'&&camera===perspective){const desired=new T.Vector3(x,1,z);const delta=desired.sub(controls.target).multiplyScalar(dt*2.1);controls.target.add(delta);camera.position.add(delta);}
}
function checkPaths(){ensurePersonFree();const p=personPos();const lines=['bed','desk','bathroom','balcony','entrance'].map(name=>{const opts=destination(name,state.items),pass=opts.some(o=>findPath(p,o,state.items,personHeight));return{name,pass,exists:!!opts.length};});$('#pathResults').innerHTML=lines.map(r=>`<div><span>${r.name[0].toUpperCase()+r.name.slice(1)}</span><b class="${r.pass?'pass':'fail'}">${r.pass?'✓ Reachable':r.exists?'Blocked':'Not placed'}</b></div>`).join('');toast('Access checked from Blocky’s current position.');return lines;}

function exportLayout(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});download(blob,'House-Studio-Layout.json');toast('Layout exported. Keep this file as your portable backup.');}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function savedLayouts(){const values=readStorage('house-studio-layouts-v1',[]);return Array.isArray(values)?values:[];}
function renderSaved(){const layouts=savedLayouts();$('#savedLayouts').innerHTML=layouts.length?layouts.map((p,i)=>`<div class="saved-layout"><button data-load="${i}">${escapeHTML(p.name)}<small>${p.items?.length||0} objects</small></button><button class="icon-btn" data-remove-save="${i}" title="Delete saved copy" aria-label="Delete ${escapeHTML(p.name)}">${icon('trash')}</button></div>`).join(''):'<div class="empty-copy">No named copies yet.</div>';$$('[data-load]').forEach(b=>b.onclick=()=>{try{const s=validateLayout(layouts[Number(b.dataset.load)]);checkpoint();state=s;selectedId=null;commit();$('#layoutsDialog').close();toast('Saved layout loaded.');}catch(e){toast(e.message);}});$$('[data-remove-save]').forEach(b=>b.onclick=()=>{if(!confirm('Remove this named copy? Your current layout stays unchanged.'))return;layouts.splice(Number(b.dataset.removeSave),1);writeStorage('house-studio-layouts-v1',layouts);renderSaved();});}
function present(active){document.body.classList.toggle('presentation',active);$('#exitPresent').hidden=!active;selectedId=null;updateSelection();$('#sidebar').classList.remove('mobile-open');resize();}
function screenshot(){renderer.render(scene,camera);renderer.domElement.toBlob(blob=>{if(blob)download(blob,'House-Studio-View.png');});toast('Scene image saved.');}

$$('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$$('[data-light]').forEach(b=>b.onclick=()=>setLight(b.dataset.light));$$('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));
$('#roofBtn').onclick=()=>{showRoof=!showRoof;if(showRoof&&wallMode==='hidden'){wallMode='full';$('#wallSelect').value=wallMode;}applyVisibility();};$('#wallSelect').onchange=e=>{wallMode=e.target.value;applyVisibility();};$('#fitBtn').onclick=()=>view('iso');$('#lightsToggle').onchange=updateLights;$('#gardenToggle').onchange=e=>house.garden.visible=e.target.checked;
$('#measureBtn').onclick=toggleMeasure;$('#dimensionBtn').onclick=()=>{dimensionGroup.visible=!dimensionGroup.visible;$('#dimensionBtn').classList.toggle('active',dimensionGroup.visible);};$('#undoBtn').onclick=undo;$('#redoBtn').onclick=redo;$('#snapToggle').onchange=e=>{snap=e.target.checked;grid.visible=mode==='decorate'&&snap;renderInspector();};$('#searchInput').oninput=renderCatalog;
$('#heightInput').oninput=e=>{personHeight=Number(e.target.value)/100;$('#heightLabel').textContent=e.target.value+' cm';stopWalking();};$('#followToggle').onchange=e=>follow=e.target.checked;$('#pathToggle').onchange=e=>routeGroup.visible=e.target.checked;$('#stopPerson').onclick=()=>{const a=walking.action;if(a?.item&&walking.phase!=='walking'){blocky.root.position.set(a.x,surfaceHeight(a.x,a.z)+.015,a.z);}stopWalking();};$('#resetPerson').onclick=resetPerson;$('#checkPaths').onclick=checkPaths;
$('#cameraTourBtn').onclick=()=>{if(camera===ortho)view('iso');autoOrbit=!autoOrbit;$('#cameraTourBtn').innerHTML=icon(autoOrbit?'pause':'play');};$('#screenshotBtn').onclick=screenshot;$('#helpBtn').onclick=()=>$('#helpDialog').showModal();$('#referenceBtn').onclick=()=>{$('#helpDialog details').open=true;$('#helpDialog').showModal();};$$('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('#saveBtn').onclick=()=>{renderSaved();$('#layoutsDialog').showModal();};$('#saveLayoutForm').onsubmit=e=>{e.preventDefault();const name=$('#layoutName').value.trim();if(!name)return;const list=savedLayouts();if(list.length>=25){toast('Export or remove a saved copy before adding more (limit 25).');return;}const data=JSON.parse(JSON.stringify({...state,name}));list.push(data);if(writeStorage('house-studio-layouts-v1',list)){renderSaved();toast('Named copy saved.');}else toast('Browser storage is full or unavailable. Export JSON instead.');};$('#exportBtn').onclick=exportLayout;$('#downloadLayoutBtn').onclick=exportLayout;$('#importBtn').onclick=()=>$('#importFile').click();$('#importFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>2e6){toast('Layout file is too large (maximum 2 MB).');return;}try{const value=validateLayout(JSON.parse(await file.text()));checkpoint();state=value;selectedId=null;commit();$('#layoutsDialog').close();toast('Layout imported.');}catch(err){toast('Import stopped: '+err.message);}};
