// Structural editor: all changes persist in the same undoable/exportable layout as furniture.
const buildingParts=[['floor','Main floor / footprint'],['front-wall','Front wall'],['back-wall','Rear wall'],['left-wall','Left wall'],['right-wall','Right wall'],['bathroom','Bathroom — move entire room'],['balcony','Balcony'],['roof','Main roof'],['bath-roof','Bathroom roof'],['garden','Garden / surroundings']];
const paletteLabels={wall:'General walls',floor:'Main floor',foundation:'Foundation',bathWall:'Bathroom walls',bathFloor:'Bathroom floor',roof:'Main roof',bathRoof:'Bathroom roof',balcony:'Balcony deck',rail:'Balcony rails',door:'Doors',window:'Window glass',frame:'Door/window frames',trim:'Wall trim',garden:'Garden'};
const numericField=(key,label,value,min=-6,max=6,step=.05)=>`<label class="field-label">${label}<input type="number" data-build-field="${key}" min="${min}" max="${max}" step="${step}" value="${Number(value).toFixed(2)}"></label>`;
const colorField=(key,label,color)=>`<label class="field-label">${label}<input type="color" data-build-color="${key}" value="${color}"></label>`;
function structurePart(){return state.structure.openings.find(o=>o.id===selectedStructure)||state.structure.partitions.find(o=>o.id===selectedStructure);}
function selectStructure(id){selectedStructure=id;renderBuild();}
function moveBathroomContents(oldRoom,newRoom){const dx=newRoom.x-oldRoom.x,dz=newRoom.z-oldRoom.z,scaleX=newRoom.w/oldRoom.w,scaleZ=newRoom.d/oldRoom.d;
 for(const o of state.items){if(o.x>=oldRoom.x-oldRoom.w/2&&o.x<=oldRoom.x+oldRoom.w/2&&o.z>=oldRoom.z-oldRoom.d/2&&o.z<=oldRoom.z+oldRoom.d/2){o.x=newRoom.x+(o.x-oldRoom.x)*scaleX;o.z=newRoom.z+(o.z-oldRoom.z)*scaleZ;}}
}
function editStructure(mutator){const before=JSON.stringify(state.structure),oldRoom={...state.structure.bathroom};checkpoint();mutator(state.structure);const s=state.structure,b=s.bounds,q=s.bathroom;
 if(b.right-b.left<2||b.front-b.back<2||q.w<.8||q.d<.8||s.openings.some(o=>o.sill+o.h>3||o.sill+o.h<.3)){state.structure=JSON.parse(before);history.pop();updateHistory();renderBuild();toast('That edit would make the room too small or place an opening above the wall.');return;}
 if(q.x!==oldRoom.x||q.z!==oldRoom.z||q.w!==oldRoom.w||q.d!==oldRoom.d)moveBathroomContents(oldRoom,q);
 state.preset='custom';commit();}
function renderBuild(){const s=state.structure;if(!s)return;const parts=[...buildingParts,...s.openings.map(o=>[o.id,`${o.kind==='door'?'🚪':'▤'} ${o.id} · ${o.side}`]),...s.partitions.map((p,i)=>[p.id,`Interior wall ${i+1}`])];
 $('#buildList').innerHTML=parts.map(([id,name])=>`<button data-build-select="${escapeHTML(id)}" class="${selectedStructure===id?'active':''}"><span>${escapeHTML(name)}</span>${selectedStructure===id?'<small>EDITING</small>':'<small>→</small>'}</button>`).join('');
 $$('[data-build-select]').forEach(el=>el.onclick=()=>selectStructure(el.dataset.buildSelect));
 $('#buildPalette').innerHTML=Object.entries(paletteLabels).map(([key,label])=>`<label><input type="color" value="${s.colors[key]}" data-palette="${key}"><span>${label}</span></label>`).join('');
 $$('[data-palette]').forEach(el=>el.onchange=e=>editStructure(s=>s.colors[el.dataset.palette]=e.target.value));
 const b=s.bounds,q=s.bathroom,part=structurePart();let title='',content='';
 if(selectedStructure==='floor'){title='Main floor & outer walls';content=`<p class="small-note">Move any exterior wall independently by editing its boundary. Floor, roof and adjoining edges follow.</p><div class="row">${numericField('bounds.left','Left X',b.left,-5,2)}${numericField('bounds.right','Right X',b.right,-2,5)}</div><div class="row">${numericField('bounds.back','Rear Z',b.back,-5,2)}${numericField('bounds.front','Front Z',b.front,-2,5)}</div>${colorField('colors.floor','Floor color',s.colors.floor)}<p class="small-note">Width ${(b.right-b.left).toFixed(2)} m × depth ${(b.front-b.back).toFixed(2)} m.</p>`;}
 else if(['front-wall','back-wall','left-wall','right-wall'].includes(selectedStructure)){const k={'front-wall':'front','back-wall':'back','left-wall':'left','right-wall':'right'}[selectedStructure],colorKey=k+'Wall';title=k[0].toUpperCase()+k.slice(1)+' exterior wall';content=`<p class="small-note">Move this wall. The main floor and roof resize with it; openings retain their absolute positions until you move them.</p>${numericField('bounds.'+k,k==='front'||k==='back'?'Z position':'X position',b[k],-5,5)}${colorField('colors.'+colorKey,'This wall color',s.colors[colorKey]||s.colors.wall)}`;}
 else if(selectedStructure==='bathroom'){title='Entire bathroom';content=`<p class="small-note">Drag the bathroom in the 3D scene, or move and resize it here. The bathroom walls, floor, roof and openings move together. Re-align access doors after changing its position.</p><div class="row">${numericField('bathroom.x','Center X',q.x)}${numericField('bathroom.z','Center Z',q.z)}</div><div class="row">${numericField('bathroom.w','Width',q.w,.8,4)}${numericField('bathroom.d','Depth',q.d,.8,4)}</div>${colorField('colors.bathWall','Bathroom wall color',s.colors.bathWall)}${colorField('colors.bathFloor','Bathroom floor color',s.colors.bathFloor)}`;}
 else if(selectedStructure==='balcony'){title='Rear balcony';content=numericField('balcony.depth','Depth',s.balcony.depth,.5,3)+colorField('colors.balcony','Deck color',s.colors.balcony)+colorField('colors.rail','Rail color',s.colors.rail);}
 else if(selectedStructure==='roof'||selectedStructure==='bath-roof'){title=selectedStructure==='roof'?'Main roof':'Bathroom roof';const k=selectedStructure==='roof'?'roof':'bathRoof';content=colorField('colors.'+k,'Roof color',s.colors[k])+'<p class="small-note">The roof follows the underlying walls and floor dimensions automatically.</p>';}
 else if(selectedStructure==='garden'){title='Garden';content=colorField('colors.garden','Ground color',s.colors.garden);}
 else if(part?.kind){title=part.kind==='door'?'Door':'Window';const w=wallSpec(s,part.side);content=`<label class="field-label">Wall<select data-build-field="opening.side">${SIDES.map(side=>`<option value="${side}" ${part.side===side?'selected':''}>${side}</option>`).join('')}</select></label><div class="row">${numericField('opening.at',w.axis==='x'?'X position':'Z position',part.at)}${numericField('opening.w','Opening width',part.w,.4,3)}</div><div class="row">${numericField('opening.h','Height',part.h,.3,2.7)}${numericField('opening.sill','Sill height',part.sill,0,2.5)}</div>${colorField('opening.color','Individual '+part.kind+' color',part.color||s.colors[part.kind])}<p class="small-note">Drag this ${part.kind} in the 3D scene to slide it along its current wall. Moving a bathroom access door may require matching the adjacent wall opening.</p><button id="deleteStructure" class="btn secondary wide">Delete ${part.kind}</button>`;}
 else if(part){title='Interior wall';content=`<p class="small-note">Drag to move this wall. Change width and depth to extend it or turn it into a partition.</p><div class="row">${numericField('partition.x','Center X',part.x)}${numericField('partition.z','Center Z',part.z)}</div><div class="row">${numericField('partition.w','Width',part.w,.1,6)}${numericField('partition.d','Depth',part.d,.1,6)}</div><div class="row">${numericField('partition.h','Height',part.h,.3,3)}${numericField('partition.deg','Rotation °',(part.rot||0)*180/Math.PI,-360,360,15)}</div>${colorField('partition.color','Individual wall color',part.color)}<button id="deleteStructure" class="btn secondary wide">Delete wall</button>`;}
 else {title='Select a structure';content='<p class="helper">Choose a component to edit its size, position and color.</p>';}
 const issues=structuralIssues(s);if(issues.length)content+=issues.map(t=>`<p class="warning">${escapeHTML(t)}</p>`).join('');
 $('#buildInspectorTitle').textContent=title;$('#buildInspector').innerHTML=content;
 $$('[data-build-field]').forEach(el=>el.onchange=e=>{let value=el.type==='number'?Number(el.value):el.value;if(el.type==='number'&&(!Number.isFinite(value)||value<Number(el.min)||value>Number(el.max))){toast('Check the allowed dimension range.');renderBuild();return;}const path=el.dataset.buildField.split('.');editStructure(s=>{const target=path[0]==='opening'?s.openings.find(o=>o.id===selectedStructure):path[0]==='partition'?s.partitions.find(o=>o.id===selectedStructure):s[path[0]];if(!target)return;if(path[1]==='deg')target.rot=value*Math.PI/180;else {target[path[1]]=value;if(path[0]==='opening'&&path[1]==='side'){const wall=wallSpec(s,target.side);target.at=Math.min(wall.end-target.w/2-.1,Math.max(wall.start+target.w/2+.1,target.at));}}});});
 $$('[data-build-color]').forEach(el=>el.onchange=e=>{const path=el.dataset.buildColor.split('.');editStructure(s=>{if(path[0]==='opening'){s.openings.find(o=>o.id===selectedStructure).color=e.target.value;}else if(path[0]==='partition'){s.partitions.find(o=>o.id===selectedStructure).color=e.target.value;}else s.colors[path[1]]=e.target.value;});});
 if($('#deleteStructure'))$('#deleteStructure').onclick=()=>{editStructure(s=>{s.openings=s.openings.filter(o=>o.id!==selectedStructure);s.partitions=s.partitions.filter(o=>o.id!==selectedStructure);});selectedStructure='floor';renderBuild();};
}
function structureHit(e){ray(e);const hits=raycaster.intersectObjects([house.structure,house.full,house.cut,house.doors,house.roof,house.garden],true);for(const h of hits){let n=h.object;while(n){if(n.userData.structureId)return n.userData.structureId;n=n.parent;}}return null;}
function moveStructure(id,x,z){const s=state.structure,step=snap?.1:.01,round=n=>Math.round(Math.max(-5.5,Math.min(5.5,n))/step)*step;
 if(id==='bathroom'){const oldRoom={...s.bathroom};s.bathroom.x=round(x);s.bathroom.z=round(z);moveBathroomContents(oldRoom,s.bathroom);return true;}
 const opening=s.openings.find(o=>o.id===id);if(opening){const w=wallSpec(s,opening.side),low=w.start+opening.w/2+.1,high=w.end-opening.w/2-.1;opening.at=round(Math.max(low,Math.min(high,w.axis==='x'?x:z)));return true;}
 const wall=s.partitions.find(o=>o.id===id);if(wall){wall.x=round(x);wall.z=round(z);return true;}
 if(['front-wall','back-wall','left-wall','right-wall'].includes(id)){const key=id.split('-')[0],b=s.bounds;const raw=round(['left','right'].includes(key)?x:z);s.bounds[key]=Math.max(key==='right'?b.left+2:key==='front'?b.back+2:-5.5,Math.min(key==='left'?b.right-2:key==='back'?b.front-2:5.5,raw));return true;}return false;}
$('#addPartition').onclick=()=>{const id=uid();editStructure(s=>s.partitions.push({id,x:0,z:0,w:2,d:.15,h:3,rot:0,color:s.colors.wall}));selectStructure(id);toast('Interior wall added. Drag it or set exact dimensions.');};
for(const kind of ['Door','Window'])$('#add'+kind).onclick=()=>{if(state.structure.openings.length>=40){toast('Maximum 40 openings.');return;}const id=`${kind.toLowerCase()}-${Date.now().toString(36)}`;editStructure(s=>s.openings.push({id,kind:kind.toLowerCase(),side:'front',at:s.bounds.left+.7,w:kind==='Door'?.8:1,h:kind==='Door'?2:1.1,sill:kind==='Door'?0:1}));selectStructure(id);toast(kind+' added. Change its wall or position as needed.');};
$('#resetStructure').onclick=()=>{if(!confirm('Reset the house structure, doors, windows and all structural colors? Your furniture will remain unchanged.'))return;editStructure(s=>Object.assign(s,cloneStructure()));selectedStructure='floor';renderBuild();};
let lastStructurePreview=0;
renderer.domElement.addEventListener('pointerdown',e=>{if(mode!=='build'||e.button!==0||measureMode)return;const id=structureHit(e);if(!id)return;selectStructure(id);const p=pointAt(e);if(!p)return;
 const s=state.structure;const draggable=id==='bathroom'||['front-wall','back-wall','left-wall','right-wall'].includes(id)||s.openings.some(o=>o.id===id)||s.partitions.some(o=>o.id===id);
 if(!draggable)return;let center={x:p.x,z:p.z};if(id==='bathroom')center={x:s.bathroom.x,z:s.bathroom.z};else if(s.partitions.some(o=>o.id===id)){const o=s.partitions.find(o=>o.id===id);center={x:o.x,z:o.z};}
 buildDrag={id,pointerId:e.pointerId,startX:e.clientX,startY:e.clientY,offsetX:center.x-p.x,offsetZ:center.z-p.z,started:false};controls.enabled=false;renderer.domElement.setPointerCapture(e.pointerId);
},true);
renderer.domElement.addEventListener('pointermove',e=>{if(!buildDrag||mode!=='build'||e.pointerId!==buildDrag.pointerId)return;
 if(!buildDrag.started){if(Math.hypot(e.clientX-buildDrag.startX,e.clientY-buildDrag.startY)<5)return;checkpoint();buildDrag.started=true;}
 const p=pointAt(e);if(!p)return;moveStructure(buildDrag.id,p.x+buildDrag.offsetX,p.z+buildDrag.offsetZ);
 if(performance.now()-lastStructurePreview>85){rebuildStructure();lastStructurePreview=performance.now();}
});
function finishBuildDrag(e){if(!buildDrag||e.pointerId!==buildDrag.pointerId)return;if(buildDrag.started){state.preset='custom';commit(false);}buildDrag=null;controls.enabled=true;}
renderer.domElement.addEventListener('pointerup',finishBuildDrag);
renderer.domElement.addEventListener('pointercancel',finishBuildDrag);
