const clock=new T.Clock();function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.05),time=clock.elapsedTime;if(cameraTransition){cameraTransition.t+=dt;const t=Math.min(1,cameraTransition.t/.65),e=t*t*(3-2*t);camera.position.lerpVectors(cameraTransition.from,cameraTransition.to,e);controls.target.lerpVectors(cameraTransition.targetFrom,cameraTransition.targetTo,e);if(t===1)cameraTransition=null;}controls.autoRotate=autoOrbit;controls.autoRotateSpeed=.60;controls.update(dt);if(mode==='simulate')updatePerson(dt,time);renderer.render(scene,camera);}animate();$('#loading').hidden=true;
